WITH cleaned AS (SELECT *, COALESCE(quantity, 0) AS quantity_filled FROM inventory WHERE last_restock > TO_DATE('2023-09-13')), with_dims AS (SELECT e.*, d.brand, d.launch_date FROM cleaned e LEFT JOIN products d ON e.product_id = d.id), scored AS (SELECT *, AVG(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_quantity, MAX(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_quantity, MIN(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_quantity FROM with_dims), scored_inventory AS (SELECT id, store_id, last_restock, brand, launch_date, running_avg_quantity, running_min_quantity, SUM(quantity) OVER (ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, SUM(running_avg_quantity) OVER (PARTITION BY product_id) AS product_id_sum_running_avg_quantity FROM scored) SELECT id, last_restock, brand, running_avg_quantity, running_min_quantity, CUME_DIST() OVER w_grp AS running_min_quantity_cume_dist, SUM(running_min_quantity) OVER w_hist AS running_running_min_quantity FROM scored_inventory WINDOW w_grp AS (ORDER BY running_min_quantity DESC NULLS FIRST), w_hist AS (PARTITION BY brand ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
